/// Boot re-adoption (issue #2201 AC5): a manifest entry whose pid is
/// alive at boot becomes a real registry job instead of an invisible
/// ghost. The manifest id is KEPT — board resume matching and
/// `bash_job` id resolution keep working. Issue #2265: because the id
/// is kept, a harness-NATIVE job's log (`$dir/$id.log`, issue #1408
/// co-location) is still on disk — the adopted entry resolves it and
/// stays output-capable instead of degrading to liveness-only.
Future<ShellJobEntry> adoptRunningEntry({
  required String id,
  required String command,
  required int pid,
  String? pidStart,
  int? startedAtMs,
}) async {
  // Idempotent (issue #2201 r3): captureLostJobs runs at every boot —
  // a wake/continuation loop re-boots the same CLI instance — and
  // adoption never rewrites the manifest, so a second boot re-hands
  // every still-live entry here. The existing entry stays
  // authoritative: one registry row, one onStart, one settle notice.
  for (final entry in _jobs) {
    if (entry.id == id) return entry;
  }
  return _adopt(
    id: id,
    command: command,
    pid: pid,
    pidStart: pidStart,
    logPath: await _adoptedLogPath(id),
    startedAt: startedAtMs == null
        ? null
        : DateTime.fromMillisecondsSinceEpoch(startedAtMs),
  );
}

/// The kept-id job's original harness log, or '' when there is none:
/// foreign survivors have no file at the derivable path, and neither
/// has a native log deleted between runs (retention sweep) — both fall
/// back to the honest liveness-only surfaces.
Future<String> _adoptedLogPath(String id) async {
  final baseEnv = env;
  final path = '${jobLogDir ?? '${baseEnv.cwd}/.fah/bash_jobs'}/$id.log';
  final exists = await baseEnv.exists(path);
  return exists.valueOrNull == true ? path : '';
}

ShellJobEntry _adopt({
  required String id,
  required String command,
  required int pid,
  String? pidStart,
  String logPath = '',
  DateTime? startedAt,
}) {
  final entry = ShellJobEntry._(
    _AdoptedShellJob(
      id: id,
      command: command,
      pid: pid,
      startTag: pidStart ?? '',
      stopProcess: stopAdoptedOverride ?? stopDetachedProcess,
      livenessSample: livenessTableOverride ?? _probeLivenessTable,
      logPath: logPath,
    ),
    adopted: true,
    startedAt: startedAt,
  );
  _jobs.add(entry);
  _listenSettle(entry);
  onStart?.call(entry);
  _ensureAdoptedPoll();
  return entry;
}

/// Cadence between adoption liveness samples: cheap (one `ps` per tick
/// only while an adopted job runs) and fast enough that a completion
/// notice lands well inside any human-relevant window.
static const adoptedLivenessPollInterval = Duration(seconds: 5);

Timer? _adoptedPoll;
final _adoptedLastNotice = <String, DateTime>{};

bool get _hasRunningAdopted => _jobs.any((e) => e.isAdopted && e.isRunning);

void _ensureAdoptedPoll() {
  if (_adoptedPoll != null || !_hasRunningAdopted) return;

  if (all) {
    return ToolExecutionResult.text(
      everything.map(_shellJobStatusLine).join('\n'),
    );
  }
  final running = [
    for (final entry in everything)
      if (entry.isRunning) entry,
  ];
  final exited = [
    for (final entry in everything)
      if (!entry.isRunning) entry,
  ]..sort(_bySettledDescending);
  final shown = exited.take(_statusExitedLimit).toList();
  final lines = [
    ...running.map(_shellJobStatusLine),
    ...shown.map(_shellJobStatusLine),
    if (exited.length > shown.length)
      '… ${exited.length - shown.length} more exited job(s) not shown '
          '(${exited.length} exited total, logs stay in .fah/bash_jobs/) — '
          'pass all: true to list every job.',
  ];
  return ToolExecutionResult.text(lines.join('\n'));
}

/// The with-id `status` result. gh-1459 ask #4: a status probe of a
/// resolved job counts as liveness for the headless drain's liveness leg.
ToolExecutionResult _bashJobStatusLookup(ShellJobRegistry jobs, String id) {
  final lookup = jobs.lookup(id);
  switch (lookup) {
    case ShellJobHit(:final entry):
      entry.markProbed();
    case ShellJobNearMiss(:final entry):
      entry.markProbed();
    case ShellJobPrefixAmbiguous():
    case ShellJobUnknownId():
  }
  return switch (lookup) {
    ShellJobHit(:final entry) => ToolExecutionResult.text(
      _shellJobStatusLine(entry),
    ),
    ShellJobNearMiss(:final entry) => ToolExecutionResult.text(
      '${_staleIdNote(lookup.id, entry.id)}\n'
      '${_shellJobStatusLine(entry)}\n'
      '${_resolvedStateLine(entry)}',
    ),
    ShellJobPrefixAmbiguous(:final entries) => ToolExecutionResult.text(
      _ambiguousText(lookup.id, entries),
    ),
    ShellJobUnknownId(:final closestIds) => ToolExecutionResult.text(
      _unknownIdText(
        jobs,
        lookup.id,
        closestIds,
        gcNote: _statusUnknownText(jobs, lookup.id, closestIds),
      ),
    ),
  };
}

/// The `status` unknown-id flow: malformed ids dead-end with the shortest
/// error (E3), GC'd ids render the honest compacted note, everything else
/// gets the plain closest-ids result (AC2).
String _statusUnknownText(
  ShellJobRegistry jobs,
  String id,
  List<String> closestIds,
) {
  if (parseShellJobIdParts(id) == null) {
    throw StateError('unknown background job: $id');
  }
  return _unknownIdText(jobs, id, closestIds, gcNote: _gcStatusNote(jobs, id));
}

Future<ToolExecutionResult> _bashJobOutputResult(
  ShellJobRegistry jobs,
  String? id,
  int? lines,
) async {
  if (id == null) throw StateError('bash_job output requires an id');
  final maxLines = lines ?? 50;
  final lookup = jobs.lookup(id);
  switch (lookup) {
    case ShellJobHit(:final entry):
      // gh-1459 ask #4: reading the job's log is the model probing it —
      // it counts as liveness for the drain's liveness leg.
      entry.markProbed();
      // Issue #2201 AC3 / #2265: adopted jobs with no harness log keep
      // the honest adopted-explanation; a boot re-adopted native job
      // (kept id ⇒ derivable log) tails its real file like any native
      // job.
      if (entry.isAdopted) {
        return _adoptedOutputResult(jobs, entry, maxLines);
      }
      return ToolExecutionResult.text(
        await _exactOutputText(jobs, entry, maxLines),
      );
    case ShellJobNearMiss(:final entry):
      entry.markProbed();
      final tail = await jobs.tail(entry.id, maxLines: maxLines);
      return ToolExecutionResult.text(
        '${_staleIdNote(lookup.id, entry.id)}\n'
        '${tail.isEmpty ? '(no output yet)' : tail}\n'
        '${_resolvedStateLine(entry)}',
      );
    case ShellJobPrefixAmbiguous(:final entries):
      return ToolExecutionResult.text(_ambiguousText(lookup.id, entries));
    case ShellJobUnknownId(:final closestIds):
      return _unknownOutputResult(jobs, lookup.id, closestIds, maxLines);
  }
}

/// The `bash_job output` answer for an adopted job (issue #2201 AC3,
/// #2265): a foreign survivor (or a log deleted since adoption —
/// `tailFromLog` returns null) gets the adopted-explanation, never an
/// empty-log reading; a native-identifiable job tails its real harness
/// log under the same line cap as the native path.
Future<ToolExecutionResult> _adoptedOutputResult(
  ShellJobRegistry jobs,
  ShellJobEntry entry,
  int maxLines,
) async {
  final logPath = entry.logPath;
  final tail = logPath.isEmpty
      ? null
      : await jobs.tailFromLog(logPath, maxLines: maxLines);
  if (tail == null) {
    return ToolExecutionResult.text(adoptedJobOutputText(entry));
  }
  return ToolExecutionResult.text(
    '${tail.isEmpty ? '(no output)' : tail}\n'
    'Tail of $logPath — the harness log captured by the original run '
    '(adopted; no exit code — not our child).',
  );
}

/// The unknown-id `output` flow: malformed ids dead-end with the shortest
/// error (E3), GC'd ids fall back to the on-disk log while it exists (AC4)
/// or degrade to the clean error once it is gone (E2), and everything else
/// gets the plain closest-ids result (AC2).
Future<ToolExecutionResult> _unknownOutputResult(
  ShellJobRegistry jobs,
  String id,
  List<String> closestIds,
  int maxLines,
) async {
  if (parseShellJobIdParts(id) == null) {
    throw StateError('unknown background job: $id');
  }
  final gcPath = jobs.prunedLogPath(id);
  if (gcPath != null) {
    final tail = await jobs.tailFromLog(gcPath, maxLines: maxLines);
    if (tail == null) throw StateError('unknown background job: $id');
    return ToolExecutionResult.text(
      'Job $id already exited; its log was compacted out of the registry. '
      'Tail from disk:\n'
      '${tail.isEmpty ? '(no output)' : tail}',
    );
  }
  return ToolExecutionResult.text(_unknownIdText(jobs, id, closestIds));
}

/// Issue #2201: the pre-stop honest wording for a job that is already
/// done — an adopted job has no exit code to report (liveness-only), a
/// registry-native job reports its real one. Null when [entry] still
/// runs (the caller proceeds to stop it).
ToolExecutionResult? _alreadyFinishedStopResult(
  ShellJobEntry entry,
  String id,
) {
  if (entry.isRunning) return null;
  return ToolExecutionResult.text(
    entry.isAdopted
        ? '$id already exited (adopted — liveness-only, no exit code)'
        : '$id already finished (exit code ${entry.exitCode})',
  );
}

/// Issue #2201 r3: `ShellJobEntry.stop` re-verifies the #478 start tag
/// before signaling. When the guard refused — the process was already
/// gone, or its pid was recycled onto a stranger — nothing was signaled,
/// so "Stopped" would be a lie. Null when the stop ran normally.
ToolExecutionResult? _refusedAdoptedStopResult(ShellJobEntry entry, String id) {
  if (entry.isRunning || !entry.isAdopted || entry.stopReason != null) {
    return null;
  }
  return ToolExecutionResult.text(
    '$id already exited (adopted — liveness-only, no exit code)',
  );
